 static string CurveHash(AnimationClip source){using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,System.Text.Encoding.UTF8,true))foreach(var b in AnimationUtility.GetCurveBindings(source).Where(b=>b.type==typeof(Transform)).OrderBy(b=>b.path).ThenBy(b=>b.propertyName)){w.Write(b.path);w.Write(b.propertyName);var c=AnimationUtility.GetEditorCurve(source,b);w.Write((int)c.preWrapMode);w.Write((int)c.postWrapMode);w.Write(c.length);foreach(var k in c.keys){w.Write(k.time);w.Write(k.value);w.Write(k.inTangent);w.Write(k.outTangent);w.Write(k.inWeight);w.Write(k.outWeight);w.Write((int)k.weightedMode);}}using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(m.ToArray())).Replace("-","").ToLowerInvariant();}}
 public static readonly string[] States={"Victory","Greeting","Dance","Defeat","Walk","NativeBox02","NativeFrontKick","NativeHeadFull"};public static readonly string[] Sources={"cheer","greet_01","dance_01","defeat_02","walk","box_02","front_kick_01","hit_to_head"};
 public static void Run(){
  const string genericPath="Assets/LighFight/Art/Drafts/TripoGalaPlayable/Source/GalaFullOriginal/model.fbx";Directory.CreateDirectory("Assets/LighFight/Art/Drafts/TripoGalaPlayable/Source/GalaFullOriginal");File.Copy("Assets/LighFight/Art/Drafts/TripoGalaPlayable/Source/GalaFull/model.fbx",genericPath,true);AssetDatabase.Refresh();var imp=(ModelImporter)AssetImporter.GetAtPath(genericPath);imp.animationType=ModelImporterAnimationType.Generic;imp.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;imp.skinWeights=ModelImporterSkinWeights.Custom;imp.maxBonesPerVertex=8;imp.minBoneWeight=0;imp.weldVertices=false;imp.meshCompression=ModelImporterMeshCompression.Off;imp.isReadable=true;imp.optimizeGameObjects=false;imp.animationCompression=ModelImporterAnimationCompression.Off;imp.SaveAndReimport();
  var human=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Art/Drafts/TripoGalaPlayable/Source/GalaFull/model.fbx").GetComponentInChildren<SkinnedMeshRenderer>();var generic=AssetDatabase.LoadAssetAtPath<GameObject>(genericPath).GetComponentInChildren<SkinnedMeshRenderer>();if(TripoGalaFullSourcePrepare.MeshHash(human.sharedMesh)!=TripoGalaFullSourcePrepare.MeshHash(generic.sharedMesh))throw new Exception("Gala Generic/Human mesh/UV/bind/weight mismatch");if(!generic.bones.Select(b=>b.name).SequenceEqual(human.bones.Select(b=>b.name)))throw new Exception("Gala bone order mismatch");
  TripoGalaCandidateBuilder.Build();var actor=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Art/Drafts/TripoGalaPlayable/GalaHumanoidCandidate.prefab"));var animator=actor.GetComponentInChildren<Animator>();var mesh=actor.GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh;var ground=actor.GetComponent<CandidateFootGrounding>();const string folder="Assets/NativeSupport/Gala";Directory.CreateDirectory(folder+"/Clips");AssetDatabase.Refresh();var clips=AssetDatabase.LoadAllAssetsAtPath(genericPath).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview")).ToArray();var entries=new List<NativeSupportOverlay.Entry>();var carriers=new List<AnimationClip>();
