  var cat=AssetDatabase.LoadAssetAtPath<NativeSupportCatalog>(folder+"/integration.asset");if(!cat){cat=ScriptableObject.CreateInstance<NativeSupportCatalog>();AssetDatabase.CreateAsset(cat,folder+"/integration.asset");}cat.character="Gala";cat.meshPreservationHash=NativeSupportIntegrationBuilder.MeshHash(mesh);cat.vertexCount=mesh.vertexCount;cat.triangleCount=mesh.triangles.Length/3;cat.hipBindAnchor=animator.transform.InverseTransformPoint(animator.GetBoneTransform(HumanBodyBones.Hips).position);cat.nativeMaxCorrection=.3f;cat.footPoints=ground.shoePoints;cat.bodyPoints=Body(mesh);cat.entries=entries.ToArray();cat.carriers=carriers.ToArray();EditorUtility.SetDirty(cat);NativeSupportIntegrationBuilder.Attach(actor,(AnimatorController)animator.runtimeAnimatorController,cat);PrefabUtility.SaveAsPrefabAsset(actor,"Assets/LighFight/Art/Drafts/TripoGalaPlayable/GalaHumanoidCandidate.prefab");UnityEngine.Object.DestroyImmediate(actor);AssetDatabase.SaveAssets();TripoGalaCurvePack.PackOnly();File.WriteAllText("GalaEvidence/full-native-definition.txt","All8 originalGeneric motions copied unchanged;4supportroles+nativeWalk+3separate diagnostic motions. No fullbox loop mislabeled guard. Entire original mesh, actual vertex count recorded in final-data; unchanged weights/binds; full-body Defeat and serialized full-shoe supports (see support-definition/final-data). Sharedcombat22 retained; independent originalHuman headreaction.");Debug.Log("AGENT_RESULT Gala full8 native catalog built fullbody="+cat.bodyPoints.Length);
