 static CandidateFootGrounding.Point[] Body(Mesh mesh){var v=mesh.vertices;var b=mesh.bindposes;var result=new CandidateFootGrounding.Point[v.Length];using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int i=0;i<v.Length;i++){var xs=new CandidateFootGrounding.Influence[counts[i]];for(int k=0;k<xs.Length;k++){var w=weights[offset+k];xs[k]=new CandidateFootGrounding.Influence{bone=w.boneIndex,weight=w.weight,bindPoint=b[w.boneIndex].MultiplyPoint3x4(v[i])};}offset+=xs.Length;result[i]=new CandidateFootGrounding.Point{influences=xs};}}return result;}
 static NativeSupportPoseData Export(AnimationClip source,string path){var data=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(path);if(!data){data=ScriptableObject.CreateInstance<NativeSupportPoseData>();AssetDatabase.CreateAsset(data,path);}data.sourceName=source.name;data.sourceCurveHash=CurveHash(source);data.duration=source.length;var bindings=AnimationUtility.GetCurveBindings(source);var joints=new List<NativeSupportPoseData.Joint>();foreach(string name in bindings.Select(b=>b.path).Distinct().OrderBy(p=>p)){var j=new NativeSupportPoseData.Joint{path=name};foreach(var binding in bindings.Where(b=>b.path==name)){if(binding.type!=typeof(Transform))throw new Exception("Unexpected original curve type");string field=binding.propertyName.StartsWith("m_LocalPosition.")?"p"+binding.propertyName.Last():binding.propertyName.StartsWith("m_LocalRotation.")?"q"+binding.propertyName.Last():binding.propertyName.StartsWith("m_LocalScale.")?"s"+binding.propertyName.Last():null;if(field==null)throw new Exception("Unsupported original channel");var c=AnimationUtility.GetEditorCurve(source,binding);typeof(NativeSupportPoseData.Joint).GetField(field).SetValue(j,new AnimationCurve(c.keys){preWrapMode=c.preWrapMode,postWrapMode=c.postWrapMode});}joints.Add(j);}data.joints=joints.ToArray();EditorUtility.SetDirty(data);return data;}
